  });
}

edits.newText:
void cycleScreen() {
  const order = [
    ScreenType.spectrum,
    ScreenType.polo,
    ScreenType.dot,
    ScreenType.void_,
    ScreenType.cassette,
  ];
  final nextType = _next(order, settings.screenConfigNotifier.value.type);
  unawaited(_cycleScreenTo(nextType));
}

Future<void> _cycleScreenTo(ScreenType type) async {
  // Preserve per-screen persisted knobs (esp. Dot's default-off
  // showSongInfo) when cycling between screen types.
  final persisted = await settings.loadScreenConfig(
    SettingsService.screenIdForType(type),
  );
  final fallback = switch (type) {
    ScreenType.spectrum => const SpectrumScreenConfig(),
    ScreenType.polo => const PoloScreenConfig(),
    ScreenType.dot => const DotScreenConfig(),
    ScreenType.void_ => const VoidScreenConfig(),
    ScreenType.cassette => const CassetteScreenConfig(),
  };
  await settings.saveScreenConfig(persisted ?? fallback);
}

